head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};


scwin.trigger1_onclick = function(e) {
	$p.executeSubmission("submission1");
};

scwin.trigger2_onclick = function(e) {
	WebSquare.layer.hideProcessMessage();
};

scwin.submission1_submitdone = function(e) {
	console.log("main submitdone");
	WebSquare.layer.hideProcessMessage();
	console.log(e);
};

scwin.submission1_submiterror = function(e) {
	console.log("main error");
	console.log(e);
};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('___processbar2_i').style.display == 'none';
	}
	scwin.unitTest = function() {
		//Unit test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "$p.hideProcessMessage()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run and Stop test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}    
	scwin.unitTest();
